  "case_id": "case-airport-bubble-throughput-punctuality",
  "language": "en",
  "style": {
    "theme": "business",
    "audience": "analyst",
    "tone": "clean, data-dense, professional"
  },
  "goal": [
    {
      "id": "five-dim-encoding",
      "insight": "Encode x=annual passenger throughput (millions), y=on-time performance (%), size=number of routes, and color=region, with prominent labels on Dubai, Tokyo Haneda, and Atlanta"
    },
    {
      "id": "throughput-punctuality-relationship",
      "insight": "Show the relationship between passenger throughput and on-time performance across the 30 airports so viewers can assess whether busier airports differ in punctuality"
    },
    {
      "id": "regional-clustering",
      "insight": "Emphasize how airports from the same region cluster or disperse in the throughput–punctuality space using distinct color groupings"
    },
    {
      "id": "notable-outliers",
      "insight": "Visually highlight Dubai (exceptionally high throughput), Tokyo Haneda (notably high on-time rate), and Atlanta (highest throughput) as labeled outliers that stand apart from the main cloud"
    },
    {
      "id": "route-network-scale",
      "insight": "Make the bubble size variation clearly convey differences in route network scale, distinguishing mega-hub airports from smaller international airports"
    }
  ]
}

