const puppeteer = require('puppeteer');
const path = require('path');

(async () => {
  const browser = await puppeteer.launch({
    headless: true,
    args: ['--no-sandbox', '--disable-setuid-sandbox']
  });
  const page = await browser.newPage();

  const htmlPath = 'file://' + path.resolve('/app/output/chart.html');
  await page.goto(htmlPath, { waitUntil: 'networkidle0' });

  // Wait for chart to render
  await page.waitForTimeout(1000);

  const chartContainer = await page.$('#chartContainer');
  const screenshot = await chartContainer.screenshot({
    type: 'png',
    path: '/app/output/result.png'
  });

  console.log('PNG saved to /app/output/result.png');
  await browser.close();
})();

